// Creating a custom feature
public class MyFeature extends Feature<NoneFeatureConfiguration> {
    public MyFeature(Codec<NoneFeatureConfiguration> codec) {
        super(codec);
    }

    @Override
    public boolean place(FeaturePlaceContext<NoneFeatureConfiguration> context) {
        LevelAccessor world = context.level();
        BlockPos origin = context.origin();

        // Place blocks
        world.setBlock(origin, Blocks.DIAMOND_BLOCK.defaultBlockState(), 2);
        return true;
    }
}

// Register the feature
public static final Feature<NoneFeatureConfiguration> MY_FEATURE = 
    new MyFeature(NoneFeatureConfiguration.CODEC);
